import{_ as p,a0 as l,w as b,s as o,I as i,x as a,a1 as n,A as t,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"在 Ubuntu 16.04 Server 上安裝 Zabbix | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu 16.04 Server 上安裝 Zabbix | LCTT (201708) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu 16.04 Server 上安裝 Zabbix | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu 16.04 Server 上安裝 Zabbix | LCTT (201708) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201708/20170705 Monitoring Server Install Zabbix on an Ubuntu 16.04 Server","title":"在 Ubuntu 16.04 Server 上安裝 Zabbix","tag":"201708","desc":""},"relativePath":"201708/20170705 Monitoring Server Install Zabbix on an Ubuntu 16.04 Server.md","filePath":"[post].md"}'),d={name:"201708/20170705 Monitoring Server Install Zabbix on an Ubuntu 16.04 Server.md"};function h(g,s,c,u,x,k){const e=l("Link");return b(),o("div",null,[s[16]||(s[16]=i("h1",{id:"在-ubuntu-16-04-server-上安裝-zabbix",tabindex:"-1"},[a("在 Ubuntu 16.04 Server 上安裝 Zabbix "),i("a",{class:"header-anchor",href:"#在-ubuntu-16-04-server-上安裝-zabbix","aria-label":"Permalink to “在 Ubuntu 16.04 Server 上安裝 Zabbix”"},"​")],-1)),i("p",null,[n(e,{href:"https://www.unixmen.com/wp-content/uploads/2017/06/zabbix_logo.png"},{default:t(()=>[...s[0]||(s[0]=[i("img",{src:"https://www.unixmen.com/wp-content/uploads/2017/06/zabbix_logo.png",alt:"Zabbix logo",title:"zabbix_logo"},null,-1)])]),_:1})]),s[17]||(s[17]=i("h3",{id:"監控服務器-什麼是-zabbix",tabindex:"-1"},[a("監控服務器 - 什麼是 Zabbix "),i("a",{class:"header-anchor",href:"#監控服務器-什麼是-zabbix","aria-label":"Permalink to “監控服務器 - 什麼是 Zabbix”"},"​")],-1)),i("p",null,[n(e,{href:"http://www.zabbix.com/"},{default:t(()=>[...s[1]||(s[1]=[a("Zabbix",-1)])]),_:1}),s[2]||(s[2]=a(" 是企業級開源分佈式監控服務器解決方案。該軟件能監控網絡的不同參數以及服務器的完整性，還允許為任何事件配置基於電子郵件的警報。Zabbix 根據存儲在資料庫（例如 MySQL）中的數據提供報告和數據可視化功能。軟件收集的每個測量指標都可以通過基於 Web 的界面訪問。",-1))]),s[18]||(s[18]=r(`<p>Zabbix 根據 GNU 通用公共許可證版本 2（GPLv2）的條款發佈，完全免費。</p><p>在本教程中，我們將在運行 MySQL、Apache 和 PHP 的 Ubuntu 16.04 server 上安裝 Zabbix。</p><h3 id="安裝-zabbix-服務器" tabindex="-1">安裝 Zabbix 服務器 <a class="header-anchor" href="#安裝-zabbix-服務器" aria-label="Permalink to “安裝 Zabbix 服務器”">​</a></h3><p>首先，我們需要安裝 Zabbix 所需的幾個 PHP 模組：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt-get install php7.0-bcmath php7.0-xml php7.0-mbstring</span></span></code></pre></div><p>Ubuntu 倉庫中提供的 Zabbix 軟件包已經過時了。使用官方 Zabbix 倉庫安裝最新的穩定版本。</p><p>通過執行以下命令來安裝倉庫軟件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget http://repo.zabbix.com/zabbix/3.2/ubuntu/pool/main/z/zabbix-release/zabbix-release_3.2-1+xenial_all.deb</span></span>
<span class="line"><span># dpkg -i zabbix-release_3.2-1+xenial_all.deb</span></span></code></pre></div><p>然後更新 <code>apt</code> 包源：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt-get update</span></span></code></pre></div><p>現在可以安裝帶有 MySQL 支持和 PHP 前端的 Zabbix 服務器。執行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt-get install zabbix-server-mysql zabbix-frontend-php</span></span></code></pre></div><p>安裝 Zabbix 代理：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt-get install zabbix-agent</span></span></code></pre></div><p>Zabbix 現已安裝。下一步是配置資料庫來存儲數據。</p><h3 id="為-zabbix-配置-mysql" tabindex="-1">為 Zabbix 配置 MySQL <a class="header-anchor" href="#為-zabbix-配置-mysql" aria-label="Permalink to “為 Zabbix 配置 MySQL”">​</a></h3><p>我們需要創建一個新的 MySQL 資料庫，Zabbix 將用來存儲收集的數據。</p><p>啓動 MySQL shell：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysql -uroot -p</span></span></code></pre></div><p>接下來：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mysql&gt; CREATE DATABASE zabbix CHARACTER SET utf8 COLLATE utf8_bin;</span></span>
<span class="line"><span>Query OK, 1 row affected (0.00 sec)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>mysql&gt; GRANT ALL PRIVILEGES ON zabbix.* TO zabbix@localhost IDENTIFIED BY &#39;usr_strong_pwd&#39;;</span></span>
<span class="line"><span>Query OK, 0 rows affected, 1 warning (0.00 sec)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>mysql&gt; EXIT;</span></span>
<span class="line"><span>Bye</span></span></code></pre></div><p>接下來，導入初始表和數據。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># zcat /usr/share/doc/zabbix-server-mysql/create.sql.gz | mysql -uzabbix -p zabbix</span></span></code></pre></div><p>輸入在 MySQL shell 中創建的 <strong>zabbix</strong> 用户的密碼。</p><p>接下來，我們需要編輯 Zabbix 服務器配置文件，它是 <code>/etc/zabbix/zabbis_server.conf</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># $EDITOR /etc/zabbix/zabbix_server.conf</span></span></code></pre></div><p>搜索文件的 <code>DBPassword</code> 部分：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>### Option: DBPassword                           </span></span>
<span class="line"><span>#       Database password. Ignored for SQLite.   </span></span>
<span class="line"><span>#       Comment this line if no password is used.</span></span>
<span class="line"><span>#                                                </span></span>
<span class="line"><span># Mandatory: no                                  </span></span>
<span class="line"><span># Default:                                       </span></span>
<span class="line"><span># DBPassword=</span></span></code></pre></div><p>取消註釋 <code>DBPassword=</code> 這行，並添加在 MySQL 中創建的密碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>DBPassword=usr_strong_pwd</span></span></code></pre></div><p>接下來，查找 <code>DBHost=</code> 這行並取消註釋。</p><p>保存並退出。</p><h3 id="配置-php" tabindex="-1">配置 PHP <a class="header-anchor" href="#配置-php" aria-label="Permalink to “配置 PHP”">​</a></h3><p>我們需要配置 PHP 來使用 Zabbix。在安裝過程中，安裝程序在 <code>/etc/zabbix</code> 中創建了一個名為 <code>apache.conf</code> 的配置文件。打開此文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># $EDITOR /etc/zabbix/apache.conf</span></span></code></pre></div><p>此時，只需要取消註釋 <code>date.timezone</code> 並設置正確的時區：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span>
<span class="line"><span>&lt;IfModule mod_php7.c&gt;</span></span>
<span class="line"><span>    php_value max_execution_time 300</span></span>
<span class="line"><span>    php_value memory_limit 128M</span></span>
<span class="line"><span>    php_value post_max_size 16M</span></span>
<span class="line"><span>    php_value upload_max_filesize 2M</span></span>
<span class="line"><span>    php_value max_input_time 300</span></span>
<span class="line"><span>    php_value always_populate_raw_post_data -1</span></span>
<span class="line"><span>    php_value date.timezone Europe/Rome</span></span>
<span class="line"><span>&lt;/IfModule&gt;</span></span></code></pre></div><p>保存並退出。</p><p>此時，重啓 Apache 並啓動 Zabbix Server 服務，使其能夠在開機時啓動：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl restart apache2</span></span>
<span class="line"><span># systemctl start zabbix-server</span></span>
<span class="line"><span># systemctl enable zabbix-server</span></span></code></pre></div><p>用 <code>systemctl</code> 檢查 Zabbix 狀態：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl status zabbix-server</span></span></code></pre></div><p>這個命令應該輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>â zabbix-server.service - Zabbix Server</span></span>
<span class="line"><span> Loaded: loaded (/lib/systemd/system/zabbix-server.service; enabled; vendor pr</span></span>
<span class="line"><span> Active: active (running) ...</span></span></code></pre></div><p>此時，Zabbix 的服務器端已經正確安裝和配置了。</p><h3 id="配置-zabbix-web-前端" tabindex="-1">配置 Zabbix Web 前端 <a class="header-anchor" href="#配置-zabbix-web-前端" aria-label="Permalink to “配置 Zabbix Web 前端”">​</a></h3><p>如介紹中所述，Zabbix 有一個基於 Web 的前端，我們將用於可視化收集的數據。但是，必須配置此接口。</p><p>使用 Web 瀏覽器，進入 URL <code>http://localhost/zabbix</code>。</p><p><img src="https://www.unixmen.com/wp-content/uploads/2017/06/snapshot1.png" alt="Zabbix monitoring server Frontend Setup"></p><p>點擊  <strong>Next step</strong></p><p><img src="https://www.unixmen.com/wp-content/uploads/2017/06/snapshot2.png" alt="snapshot2"></p><p>確保所有的值都是 <strong>Ok</strong>，然後再次單擊 <strong>Next step</strong> 。</p><p><img src="https://www.unixmen.com/wp-content/uploads/2017/06/snapshot3.png" alt="Zabbix MySQL configuration"></p><p>輸入 MySQL <strong>zabbix</strong> 的用户密碼，然後點擊 <strong>Next step</strong>。</p><p><img src="https://www.unixmen.com/wp-content/uploads/2017/06/snapshot4.png" alt="Zabbix server details"></p><p>單擊 <strong>Next step</strong> ，安裝程序將顯示具有所有配置參數的頁面。再次檢查以確保一切正確。</p><p><img src="https://www.unixmen.com/wp-content/uploads/2017/06/snapshot5.png" alt="Zabbix pre-installation details"></p><p><img src="https://www.unixmen.com/wp-content/uploads/2017/06/snapshot6.png" alt="Zabbix installation finished"></p><p>點擊 <strong>Next step</strong> 進入最後一頁。</p><p>點擊完成以完成前端安裝。默認用户名為 <strong>Admin</strong>，密碼是 <strong>zabbix</strong>。</p><h3 id="zabbix-服務器入門" tabindex="-1">Zabbix 服務器入門 <a class="header-anchor" href="#zabbix-服務器入門" aria-label="Permalink to “Zabbix 服務器入門”">​</a></h3><p><img src="https://www.unixmen.com/wp-content/uploads/2017/06/snapshot7.png" alt="Zabbix login interface"></p><p>使用上述憑證登錄後，我們將看到 Zabbix 面板：</p><p><img src="https://www.unixmen.com/wp-content/uploads/2017/06/snapshot8.png" alt="zabbix dashboard"></p><p>前往 <strong>Administration -&gt; Users</strong>，瞭解已啓用帳户的概況：</p><p><img src="https://www.unixmen.com/wp-content/uploads/2017/06/snapshot9.png" alt="Zabbix users"></p><p>通過點擊 <strong>Create user</strong> 創建一個新帳户。</p><p><img src="https://www.unixmen.com/wp-content/uploads/2017/06/snapshot10.png" alt="Zabbix User Creation"></p><p>點擊 <strong>Groups</strong> 中的 <strong>Add</strong>，然後選擇一個組：</p><p><img src="https://www.unixmen.com/wp-content/uploads/2017/06/snapshot11.png" alt="snapshot11"></p><p>保存新用户憑證，它將顯示在 <strong>Administration -&gt; Users</strong> 面板中。</p><p><strong>請注意，在 Zabbix 中，主機的訪問權限分配給用户組，而不是單個用户。</strong></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>我們結束了 Zabbix Server 安裝的教程。現在，監控基礎設施已準備好完成其工作並收集有關需要在 Zabbix 配置中添加的服務器的數據。</p><hr>`,75)),i("p",null,[s[4]||(s[4]=a("via: ",-1)),n(e,{href:"https://www.unixmen.com/monitoring-server-install-zabbix-ubuntu-16-04/"},{default:t(()=>[...s[3]||(s[3]=[a("https://www.unixmen.com/monitoring-server-install-zabbix-ubuntu-16-04/",-1)])]),_:1})]),i("p",null,[s[8]||(s[8]=a("作者：",-1)),n(e,{href:"https://www.unixmen.com/author/tutan/"},{default:t(()=>[...s[5]||(s[5]=[a("Giuseppe Molica",-1)])]),_:1}),s[9]||(s[9]=a(" 譯者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:t(()=>[...s[6]||(s[6]=[a("geekpi",-1)])]),_:1}),s[10]||(s[10]=a(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[7]||(s[7]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[13]||(s[13]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[11]||(s[11]=[a("LCTT",-1)])]),_:1}),s[14]||(s[14]=a(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...s[12]||(s[12]=[a("Linux中國",-1)])]),_:1}),s[15]||(s[15]=a(" 榮譽推出",-1))])])}const v=p(d,[["render",h]]);export{w as __pageData,v as default};
